// stable-diffusion.cpp: add near the ideogram4 include (fork line ~30):
//   #include "model/diffusion/lingbot_video.hpp"
//
// Then this else-if in the diffusion/cond construction chain (place alongside the
// sd_version_is_wan / sd_version_is_qwen_image branches). FORK convention:
// backend_for + params_backend_for, NO model_manager arg. LLMEmbedder uses the fork
// 6-arg ctor (as sd_version_is_qwen_image does at fork line 824); the runner uses the
// converted 4-arg fork ctor (backend, params_backend, tensor_storage_map, prefix) —
// upstream's trailing model_manager + sd_ctx_params->model_args args are DROPPED.
} else if (sd_version_is_lingbot_video(version)) {
    bool enable_vision = false;
    for (const auto& [name, _] : tensor_storage_map) {
        if (starts_with(name, "text_encoders.llm.visual.")) {
            enable_vision = true;
            break;
        }
    }
    cond_stage_model = std::make_shared<LLMEmbedder>(backend_for(SDBackendModule::TE),
                                                     params_backend_for(SDBackendModule::TE),
                                                     tensor_storage_map,
                                                     version,
                                                     "",
                                                     enable_vision);
    diffusion_model  = std::make_shared<LingBotVideo::LingBotVideoRunner>(backend_for(SDBackendModule::DIFFUSION),
                                                                          params_backend_for(SDBackendModule::DIFFUSION),
                                                                          tensor_storage_map,
                                                                          "model.diffusion_model");
}

